import heapq


def maxNegations(A, K=None):
    if K is None:
        K = len(A)
    heap, s = [], 0  # heap stores -x (max-heap of negated values)
    for a in A:
        s -= a
        heapq.heappush(heap, -a)
        if s <= 0 or len(heap) > K:
            x = -heapq.heappop(heap)
            s += 2 * x
    return len(heap)
